import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        int[] a = new int[n + 1], seen = new int[n + 1], path = new int[n + 1];
        for (int i = 1; i <= n; i++) a[i] = nextInt();
        Arrays.fill(seen, -1);
        int len = 0, x = 1;
        while (seen[x] < 0) {
            seen[x] = len;
            path[len++] = x;
            x = a[x];
        }
        long start = seen[x];
        long idx = k < len ? k : start + (k - start) % (len - start);
        System.out.println(path[(int) idx]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a := make([]int, n+1)
	for i := 1; i <= n; i++ {
		a[i] = nextInt()
	}
	seen := make([]int, n+1)
	for i := range seen {
		seen[i] = -1
	}
	path := []int{}
	x := 1
	for seen[x] < 0 {
		seen[x] = len(path)
		path = append(path, x)
		x = a[x]
	}
	start := seen[x]
	idx := k
	if k >= len(path) {
		idx = start + (k-start)%(len(path)-start)
	}
	fmt.Println(path[idx])
}
